//! 🔐️ Relocation preserves the original String allocation under actual Source-funded construction.
use super::*;
#[test]fn native_shared_slots_keep_original_across_relocation_and_reject_replacement(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/effect-frame.json")).unwrap();let cases=&fixture["slotCustody"];let mut original=Some(cases[0]["owner"].as_str().unwrap().to_owned());let pointer=original.as_ref().unwrap().as_ptr();let mut replacement=Some(cases[1]["candidate"].as_str().unwrap().to_owned());let original_bytes=original.as_ref().unwrap().capacity();let replacement_bytes=replacement.as_ref().unwrap().capacity();let mut bank=Bank::new(false);let mut callback=|_|true;let mut native=NativeDecodeControl::new(65536,&mut callback);let mut frame=NativeReceivingEffect::default();let mut producer=OriginalEffectAuthority::new(Commands::<SealedMode,String>{source:bank.source.clone(),mode:PhantomData});let mut slots=Slots::<SealedMode,String>::default();let d=Slots::<SealedMode,String>::capture_demand().unwrap();let work=slots.capture_work_demand(&original).unwrap();let capture=complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Capture(&mut slots,&mut original)));assert_eq!(capture.result.is_ok(),cases[0]["accepted"].as_bool().unwrap());assert!(original.is_none());
 let rejected=complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,1,Command::Capture(&mut slots,&mut replacement)));assert_eq!(rejected.result.is_ok(),cases[1]["accepted"].as_bool().unwrap());assert_eq!(replacement.as_deref(),cases[1]["candidate"].as_str());let mut slots=Box::new(slots);assert!(cases[0]["relocated"].as_bool().unwrap());assert_eq!(slots.input().unwrap().as_ptr(),pointer);
 for _ in 0..8{if slots.output_ready(){break}advance_paid(&mut bank,&mut native,&mut frame,&mut producer,&mut slots).successful().result.unwrap();}assert!(slots.output_ready());let mut output=None;let d=SealedMode::take_demand(&slots).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,1,Command::Take(&mut slots,&mut output))).result.unwrap();assert_eq!(output.as_ref().unwrap().get().as_ptr(),pointer);
 for _ in 0..4{if slots.terminal_is_empty(){break}let d=slots.close_demand(4096).unwrap();let work=slots.close_work_demand(4096).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Close(&mut slots))).result.unwrap();}assert!(slots.terminal_is_empty());let(mut owner,mut returned)=(None,None);
 for _ in 0..8{if output.is_none()&&owner.is_none(){break}let(d,work)=SealedMode::consume_demand(&output,&owner).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Consume(&mut output,&mut owner,&mut returned))).result.unwrap();}assert_eq!(returned.as_ref().unwrap().as_ptr(),pointer);assert_eq!(returned.as_deref(),cases[0]["owner"].as_str());
 for source in [&mut returned,&mut replacement]{let d=string_release_demand(source).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,1,Command::ReleaseString(source))).result.unwrap();assert!(source.is_none());}
 let wallet=bank.wallet.lock().unwrap();assert_eq!(256-wallet.fuel,native.actual_work());assert_eq!(wallet.spent.released_bytes,wallet.spent.retained_capacity_bytes+original_bytes+replacement_bytes);drop(wallet);assert!(producer.into_producer().is_ok());
}
